def calculate_order(a, m):
    """Calculates the multiplicative order of a modulo m."""
    if m == 1:
        return 1
    # Euler's totient function phi(m)
    import math
    def phi(n):
        result = n
        p = 2
        while p * p <= n:
            if n % p == 0:
                while n % p == 0:
                    n //= p
                result -= result // p
            p += 1
        if n > 1:
            result -= result // n
        return result

    phi_m = phi(m)

    # Find divisors of phi_m
    divisors = []
    for i in range(1, int(math.sqrt(phi_m)) + 1):
        if phi_m % i == 0:
            divisors.append(i)
            if i * i != phi_m:
                divisors.append(phi_m // i)
    divisors.sort()

    # Check powers
    for d in divisors:
        if pow(a, d, m) == 1:
            return d
    return phi_m # Should not happen if gcd(a, m) == 1

# Check order mod 16
L1 = calculate_order(3, 16)
print(f"Order mod 16: {L1}")

# Check order mod 625
L2 = calculate_order(3, 625)
print(f"Order mod 625: {L2}")
